// Builds supabase/production-setup.sql: every migration, in order, in one file, for
// setting up a brand-new (empty) Supabase project in a single paste.
//   npm run db:production-sql          writes the file
//   npm run db:production-sql -- --check   exits 1 if the file is out of date
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';

const folder = 'supabase/migrations/';
const files = readdirSync(folder).filter(name => name.endsWith('.sql')).sort();
const header = `-- Relofted: complete database setup for a NEW, EMPTY Supabase project.
-- Generated by scripts/build-production-sql.mjs from ${files.length} migrations. Do not edit by hand.
-- Paste the whole file into the Supabase SQL Editor and run it ONCE.
-- Never run it on a project that already has these tables (the development project does).
-- Buying starts switched off: turn it on from the Support screen when you are ready.
`;
const body = files.map(name => `\n-- ===== ${name} =====\n${readFileSync(folder + name, 'utf8').replace(/\r\n/g, '\n').trim()}\n`).join('');
const output = header + body;
const target = 'supabase/production-setup.sql';
if (process.argv.includes('--check')) {
  const current = existsSync(target) ? readFileSync(target, 'utf8').replace(/\r\n/g, '\n') : '';
  if (current !== output) { console.error(`${target} is out of date. Run: npm run db:production-sql`); process.exit(1); }
  console.log(`${target} is up to date (${files.length} migrations).`);
} else {
  writeFileSync(target, output);
  console.log(`Wrote ${target} from ${files.length} migrations.`);
}
